package jaamsim.validation;

import jaamsim.SimEntity;

/**
 * A sample validator interface for {@link jaamsim.EntityGenerator}.
 * This doesn't really do anything, and it's not a real EMF artifact.
 * It was generated by the org.eclipse.emf.examples.generator.validator plug-in to illustrate how EMF's code generator can be extended.
 * This can be disabled with -vmargs -Dorg.eclipse.emf.examples.generator.validator=false.
 */
public interface EntityGeneratorValidator {
	boolean validate();

	boolean validateFirstArrivalTime(double value);
	boolean validateInterArrivalTime(double value);
	boolean validateEntitiesPerArrival(int value);
	boolean validateMaxNumber(int value);
	boolean validatePrototype(SimEntity value);
}
